commit fa4f48d1e46c0dbef9422f794da998915a3b7615
Author: bmribler <39579120+bmribler@users.noreply.github.com>
Date:   Wed May 1 08:42:22 2024 -0400

    Fix heap-buffer-overflow in H5Fio.c (#4450)

    The buffer size for checksum was smaller than H5_SIZEOF_CHKSUM, causing an
    overflow while calculating the offset to the checksum in the buffer.

    A check was added so H5F_get_checksums would fail appropriately in all
    of its occurrences.

    Fix gh-4434

diff --git a/src/H5Fio.c b/src/H5Fio.c
index b0c24010e8..2cd8a53ba5 100644
--- a/src/H5Fio.c
+++ b/src/H5Fio.c
@@ -498,12 +498,18 @@ done:
 herr_t
 H5F_get_checksums(const uint8_t *buf, size_t buf_size, uint32_t *s_chksum /*out*/, uint32_t *c_chksum /*out*/)
 {
-    FUNC_ENTER_NOAPI_NOINIT_NOERR
+    herr_t ret_value = SUCCEED;
+
+    FUNC_ENTER_NOAPI_NOINIT

     /* Check arguments */
     assert(buf);
     assert(buf_size);

+    /* Check for buffer size smaller than H5_SIZEOF_CHKSUM */
+    if (buf_size < H5_SIZEOF_CHKSUM)
+        HGOTO_ERROR(H5E_IO, H5E_BADVALUE, FAIL, "checksum buffer is smaller than expected");
+
     /* Return the stored checksum */
     if (s_chksum) {
         const uint8_t *chk_p; /* Pointer into raw data buffer */
@@ -519,5 +525,6 @@ H5F_get_checksums(const uint8_t *buf, size_t buf_size, uint32_t *s_chksum /*out*
     if (c_chksum)
         *c_chksum = H5_checksum_metadata(buf, buf_size - H5_SIZEOF_CHKSUM, 0);

-    FUNC_LEAVE_NOAPI(SUCCEED)
+done:
+    FUNC_LEAVE_NOAPI(ret_value)
 } /* end H5F_get_chksums() */
commit 50d30bd4f01b71d02e37062ae8594884ff75ba93
Author: jhendersonHDF <jhenderson@hdfgroup.org>
Date:   Fri Mar 29 07:43:59 2024 -0500

    Fix potential buffer read overflows in H5PB_read (#4279)

    H5PB_read previously did not account for the fact that the size of the
    read it's performing could overflow the page buffer pointer, depending
    on the calculated offset for the read. This has been fixed by adjusting
    the size of the read if it's determined that it would overflow the page.

diff --git a/src/H5PB.c b/src/H5PB.c
index fc09cd56e9..69707d14cb 100644
--- a/src/H5PB.c
+++ b/src/H5PB.c
@@ -726,7 +726,7 @@ H5PB_read(H5F_shared_t *f_sh, H5FD_mem_t type, haddr_t addr, size_t size, void *
     if (H5FD_MEM_DRAW == type) {
         last_page_addr = ((addr + size - 1) / page_buf->page_size) * page_buf->page_size;

-        /* How many pages does this write span */
+        /* How many pages does this read span */
         num_touched_pages =
             (last_page_addr / page_buf->page_size + 1) - (first_page_addr / page_buf->page_size);
         if (first_page_addr == last_page_addr) {
@@ -835,6 +835,10 @@ H5PB_read(H5F_shared_t *f_sh, H5FD_mem_t type, haddr_t addr, size_t size, void *
                 offset     = (0 == i ? addr - page_entry->addr : 0);
                 buf_offset = (0 == i ? 0 : size - access_size);

+                /* Account for reads that would overflow a page */
+                if (offset + access_size > page_buf->page_size)
+                    access_size = page_buf->page_size - offset;
+
                 /* copy the requested data from the page into the input buffer */
                 H5MM_memcpy((uint8_t *)buf + buf_offset, (uint8_t *)page_entry->page_buf_ptr + offset,
                             access_size);
@@ -905,6 +909,11 @@ H5PB_read(H5F_shared_t *f_sh, H5FD_mem_t type, haddr_t addr, size_t size, void *
                 /* Copy the requested data from the page into the input buffer */
                 offset     = (0 == i ? addr - search_addr : 0);
                 buf_offset = (0 == i ? 0 : size - access_size);
+
+                /* Account for reads that would overflow a page */
+                if (offset + access_size > page_buf->page_size)
+                    access_size = page_buf->page_size - offset;
+
                 H5MM_memcpy((uint8_t *)buf + buf_offset, (uint8_t *)new_page_buf + offset, access_size);

                 /* Create the new PB entry */

